import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.t9tCn7sc.js";var i=JSON.parse(`{"title":"file_manager","description":"","frontmatter":{},"headers":[],"relativePath":"reference/server/http/middlewares/file_manager.md","filePath":"reference/server/http/middlewares/file_manager.md","lastUpdated":1793392880000}`),a={name:`reference/server/http/middlewares/file_manager.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="file-manager" tabindex="-1">file_manager <a class="header-anchor" href="#file-manager" aria-label="Permalink to “file_manager”">​</a></h1><p><code>file_manager</code> manages a directory through a browser UI and serves every file in it by path. Files can be anything: JSON, YAML, text, images or binaries. Text files open in an editor with syntax highlighting; other files are previewed or downloaded.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">server</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  http</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        file_manager</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">./data</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          prefix_path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          title</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">Shared files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    routers</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span></code></pre></div><p>With this config:</p><table tabindex="0"><thead><tr><th>Request</th><th>Result</th></tr></thead><tbody><tr><td><code>GET /files/</code></td><td>The file manager UI.</td></tr><tr><td><code>GET /files/raw/configs/app.json</code></td><td>The file, with <code>Content-Type: application/json</code>.</td></tr><tr><td><code>GET /files/raw/configs/app.yaml</code></td><td>The file, with <code>Content-Type: application/yaml</code>.</td></tr><tr><td><code>/files/api/...</code></td><td>The JSON API the UI uses, see <a href="#api">API</a>.</td></tr></tbody></table><p>The three areas never overlap: a file named <code>api/info</code> in the directory is still served at <code>/files/raw/api/info</code>.</p><p>Raw responses support <code>ETag</code>, <code>If-None-Match</code>, <code>If-Range</code>, <code>Last-Modified</code> and range requests. Directories are not listed on the raw path.</p><h2 id="etag" tabindex="-1">ETag <a class="header-anchor" href="#etag" aria-label="Permalink to “ETag”">​</a></h2><p>By default the ETag is weak (<code>W/&quot;…&quot;</code>) and built from the modification time and size, which costs nothing. Tags are compared weakly, so <code>W/&quot;x&quot;</code> and <code>&quot;x&quot;</code> match; a compress middleware in front that weakens strong tags does not break conditional requests or saves.</p><table tabindex="0"><thead><tr><th>Mode</th><th>ETag</th><th>Cost</th><th>Range resume (<code>If-Range</code>)</th></tr></thead><tbody><tr><td><code>weak</code></td><td><code>W/&quot;&lt;mtime&gt;-&lt;size&gt;&quot;</code></td><td>none</td><td>no, the full file is sent again</td></tr><tr><td><code>strong</code></td><td><code>&quot;&lt;mtime&gt;-&lt;size&gt;&quot;</code></td><td>none</td><td>yes</td></tr><tr><td><code>hash</code></td><td><code>&quot;&lt;sha256&gt;&quot;</code></td><td>first request after a change reads the whole file</td><td>yes</td></tr></tbody></table><p><code>strong</code> is safe because every write goes through a rename, so the modification time changes even when the size does not. <code>hash</code> only changes when the bytes do, so a file rewritten with the same content stays cached; hashes are kept in memory per path.</p><p>Use <code>etag_rules</code> to pick a mode per file. Patterns are <a href="https://github.com/bmatcuk/doublestar#patterns" target="_blank" rel="noreferrer">doublestar</a> globs on the path inside <code>path</code>, without a leading slash (one is stripped if given): <code>*</code> stays within a folder, <code>**</code> crosses folders, <code>{a,b}</code> lists alternatives. Rules are checked in order, the first match wins, and files matching none use <code>etag</code>. An unknown mode or a malformed pattern stops the server from starting:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">file_manager</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/srv/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  etag_rules</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">    - </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">pattern</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;videos/**&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      etag</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">strong</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">    - </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">pattern</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;**/*.{mp4,webm,mkv,iso}&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      etag</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">strong</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">    - </span><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">pattern</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">&quot;configs/**/*.json&quot;</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      etag</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">hash</span></span></code></pre></div><p>The file details panel shows the mode and current ETag of each file.</p><p>Choosing a mode:</p><ul><li>Leave the default for configs and small files; edits are protected the same way in every mode.</li><li>Use <code>strong</code> for large media, disk images and anything downloaded in parts, so interrupted downloads resume.</li><li>Use <code>hash</code> when the same content is rewritten often (generated configs, CI artefacts) and clients should keep their cache. Avoid it for very large files: the first request after each change waits for the whole file to be read.</li></ul><h3 id="how-video-playback-uses-ranges" tabindex="-1">How video playback uses ranges <a class="header-anchor" href="#how-video-playback-uses-ranges" aria-label="Permalink to “How video playback uses ranges”">​</a></h3><p>The browser never downloads a video in full before playing. It sends <code>Range: bytes=0-</code> first, the server answers <code>206 Partial Content</code>, and the browser reads the header (duration, keyframe index) and starts playing as data arrives. Seeking to minute 23 makes the browser look up that time in the index and send a new request such as <code>Range: bytes=812345678-</code>. Each request is answered by <code>http.ServeContent</code> with only those bytes.</p><p>The ETag matters when a range request depends on an earlier one: a resumed download or a player reusing cached bytes sends <code>If-Range: &lt;etag&gt;</code> to say &quot;send the rest only if the file is still the one I started&quot;. By the HTTP spec this needs a strong tag. With a weak tag the server must ignore the range and send the whole file with <code>200</code>, which for a large video means the download restarts from zero. Plain seeking in the UI player works in every mode; <code>strong</code> makes resumes and cached partial reads work too.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to “Fields”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>path</code></td><td></td><td>Directory to manage. Created when missing. Required.</td></tr><tr><td><code>prefix_path</code></td><td></td><td>Prefix stripped from the request path before lookup. Requests outside it return <code>404</code>.</td></tr><tr><td><code>read_only</code></td><td><code>false</code></td><td>Disable saving, creating, uploading, moving and deleting.</td></tr><tr><td><code>disable_ui</code></td><td><code>false</code></td><td>Serve only the raw files under <code>/raw/</code>; the UI and the API return <code>404</code>.</td></tr><tr><td><code>max_upload_size</code></td><td><code>33554432</code></td><td>Limit for a single save or upload request body, in bytes.</td></tr><tr><td><code>title</code></td><td><code>Files</code></td><td>Title shown in the UI.</td></tr><tr><td><code>cache_control</code></td><td><code>no-cache</code></td><td><code>Cache-Control</code> header for raw file responses.</td></tr><tr><td><code>etag</code></td><td><code>weak</code></td><td><code>weak</code>, <code>strong</code> or <code>hash</code>, see <a href="#etag">ETag</a>.</td></tr><tr><td><code>etag_rules</code></td><td></td><td>List of <code>{pattern, etag}</code>; picks the mode per file, first match wins.</td></tr></tbody></table><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to “UI”">​</a></h2><ul><li>Folder tree with drag and drop: drag a file or folder onto another folder to move it, or drop files and whole folders from your computer to upload them.</li><li>Previews by type: images, video and audio (played with seeking through range requests), PDF in the browser viewer, fonts with a sample text, CSV and TSV as a table, and Markdown with an edit, split or preview view.</li><li>Other binaries (archives, office documents, executables, databases) are recognised by extension and offered as a download.</li><li>Files are not downloaded in full to decide how to show them: the type comes from the extension, unknown files are sniffed from their first 8 KB, and text files over 5 MB open as a download.</li><li>Editor for text files with highlighting for about 60 languages and formats, among them JSON, YAML, TOML, INI and <code>.env</code>, XML, Markdown, HTML, CSS, SCSS, JavaScript, TypeScript, Vue, Go, Python, Rust, Java, Kotlin, C, C++, C#, Swift, PHP, Ruby, Lua, SQL, GraphQL, Protocol Buffers, Terraform, shell, PowerShell, Dockerfile, Makefile and Nginx. Files without an extension such as <code>Dockerfile</code>, <code>Makefile</code> or <code>.gitignore</code> are recognised by name.</li><li>JSON and YAML are checked as you type: problems are underlined in place, marked in the gutter and counted in the status bar (click it to jump to the first one, <code>Ctrl Shift M</code> lists all). YAML also reports duplicate keys and keeps multi-document files apart; custom tags such as CloudFormation&#39;s <code>!Ref</code> or Ansible&#39;s <code>!vault</code> are accepted. Saving a file with errors asks first. <code>.jsonc</code> and <code>.json5</code> are highlighted but not checked, since they allow comments.</li><li><strong>Format</strong> (or <code>Shift Alt F</code>) rewrites JSON and YAML with two-space indentation without changing any value: numbers keep their exact digits (big IDs, <code>1.0</code>, <code>010</code>), JSON keeps duplicate keys, and YAML keeps comments, anchors, tags and document separators. Long lines are not wrapped. Formatting is a normal edit, so <code>Ctrl Z</code> undoes it.</li><li>Code is always shown dark, in the Vesper theme used by these docs, whatever the page theme.</li><li><code>Ctrl S</code> / <code>Cmd S</code> saves. Saving is guarded by the file&#39;s ETag: when someone else saved the file after you opened it, you are asked before overwriting. Typing while a save is in flight stays marked as unsaved.</li><li>The editor never resets while you work. Saving, reloading or changes in other folders keep the cursor, scroll, folds and undo history. When the open file changes on disk and you have no unsaved edits, the new text is swapped in place; with unsaved edits it is left alone and the next save asks before overwriting. <strong>Discard</strong> also swaps the text in place, so <code>Ctrl Z</code> can bring the edits back.</li><li>Video, audio, images and PDFs are only reloaded when the file&#39;s ETag changes, so a playing video is not restarted by unrelated changes.</li><li>Every file shows its raw URL with copy and <code>curl</code> actions, and its ETag mode and value in the details panel.</li><li>Light and dark themes.</li></ul><h2 id="access-control" tabindex="-1">Access control <a class="header-anchor" href="#access-control" aria-label="Permalink to “Access control”">​</a></h2><p>The middleware has no authentication of its own. Put auth middlewares in front of it. Because raw files live under their own <code>/raw/</code> path, one middleware can serve both, with a separate router for public reads and a protected router for everything else:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">server</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">  http</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      admin_auth</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        basic_auth</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          users</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">            - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">admin:$2y$05$...</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        file_manager</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/srv/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">          prefix_path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">    routers</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files_raw</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/raw/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">      files_admin</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        path</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">: </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">/files/*</span></span>
<span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">        middlewares</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">:</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">admin_auth</span></span>
<span class="line"><span style="--shiki-light:#FFF;--shiki-dark:#FFF;">          - </span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;">files</span></span></code></pre></div><p>Raw responses carry <code>Content-Security-Policy: sandbox</code> (except PDFs) and <code>X-Content-Type-Options: nosniff</code>, so an uploaded HTML or SVG file cannot run scripts against the UI&#39;s API.</p><p>All paths are resolved inside <code>path</code>; <code>..</code> segments and symlinks pointing outside the directory are rejected.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to “API”">​</a></h2><p>The UI uses a small JSON API under <code>{prefix_path}/api/</code>. Write endpoints return <code>403</code> when <code>read_only</code> is set.</p><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>info</code></td><td>UI settings: title, read-only flag, prefix and raw path.</td></tr><tr><td><code>GET</code></td><td><code>list?path=/dir</code></td><td>Directory entries, folders first.</td></tr><tr><td><code>GET</code></td><td><code>stat?path=/x</code></td><td>One entry. For files it also has <code>etag</code> and <code>etag_mode</code>, and the <code>ETag</code> header.</td></tr><tr><td><code>GET</code></td><td><code>file?path=/x[&amp;download]</code></td><td>File content.</td></tr><tr><td><code>PUT</code></td><td><code>file?path=/x[&amp;create]</code></td><td>Write the body to the file. <code>If-Match: &lt;etag&gt;</code> (a list or <code>*</code> also works) rejects stale writes with <code>412</code>; <code>If-None-Match: *</code> writes only when the file does not exist yet; <code>create</code> fails with <code>409</code> if it exists. Missing folders are created.</td></tr><tr><td><code>DELETE</code></td><td><code>file?path=/x</code></td><td>Delete a file or a folder with its contents.</td></tr><tr><td><code>POST</code></td><td><code>mkdir</code></td><td>Body <code>{&quot;path&quot;: &quot;/dir&quot;}</code>.</td></tr><tr><td><code>POST</code></td><td><code>move</code></td><td>Body <code>{&quot;from&quot;: &quot;/a&quot;, &quot;to&quot;: &quot;/b&quot;, &quot;overwrite&quot;: false}</code>. Used for rename too.</td></tr><tr><td><code>POST</code></td><td><code>upload?path=/dir[&amp;overwrite]</code></td><td>Multipart files; file names may contain folders.</td></tr></tbody></table><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">curl</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> -X</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> PUT</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --data-binary</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> @app.yaml</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> &#39;http://localhost:8080/files/api/file?path=/configs/app.yaml&#39;</span></span></code></pre></div>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};